@st.cache_data(show_spinner=False)
def _av_photo_canvas(raw):
 """Normalize the image in memory: centered, 16:9, vehicle never distorted."""
 try:
  from PIL import Image,ImageOps
  src=Image.open(_av_io.BytesIO(raw));src=ImageOps.exif_transpose(src)
  if src.mode=='RGBA':
   white=Image.new('RGBA',src.size,(255,255,255,255));white.alpha_composite(src)
   src=white.convert('RGB')
  else:src=src.convert('RGB')
  # On nearly white studio photos, trim only excessive empty margins.
  # Never crop an outdoor/studio background with darker corners.
  w,h=src.size
  corners=(src.getpixel((0,0)),src.getpixel((w-1,0)),
           src.getpixel((0,h-1)),src.getpixel((w-1,h-1)))
  if all(min(c)>237 for c in corners) and w>100 and h>100:
   mask=ImageOps.grayscale(src).point(lambda px:255 if px<224 else 0)
   bbox=mask.getbbox()
   if bbox and (bbox[2]-bbox[0])>w*.25 and (bbox[3]-bbox[1])>h*.20:
    mx=max(16,int((bbox[2]-bbox[0])*.12))
    my=max(12,int((bbox[3]-bbox[1])*.12))
    src=src.crop((max(0,bbox[0]-mx),max(0,bbox[1]-my),
                  min(w,bbox[2]+mx),min(h,bbox[3]+my)))
  contained=ImageOps.contain(src,(1160,635),Image.Resampling.LANCZOS)
  canvas=Image.new('RGB',(1200,675),(250,250,249))
  canvas.paste(contained,((1200-contained.width)//2,(675-contained.height)//2))
  result=_av_io.BytesIO();canvas.save(result,format='JPEG',quality=89,optimize=True)
  return result.getvalue()
 except (OSError,ValueError,ImportError):return raw

@st.cache_data(show_spinner=False)
def _av_embedded_photo(key):
 return _av_b64.b64decode(_AV_USER_PHOTOS[key])

def _av_user_photo(record):
 key=_av_photo_override_key(record)
 if not key:return None
 if key in _AV_USER_PHOTOS:return _av_embedded_photo(key)
 # Optional uploaded images. No invented fallback to a different car photo.
 folder=ROOT/'autoverse_photos'
 candidates=[folder/(key+ext) for ext in ('.jpg','.jpeg','.png','.webp')]
 # Accept explicit model-year file names too, but prefer a generic file shared
 # across 2025 and 2026 for requested variants.
 candidates.extend(folder/(key+'_'+str(record['year'])+ext)
                   for ext in ('.jpg','.jpeg','.png','.webp'))
 for p in candidates:
  if p.is_file() and p.stat().st_size<=20_000_000:
   try:return _av_photo_canvas(p.read_bytes())
   except OSError:continue
 if key in _AV_USER_PHOTOS:return _av_embedded_photo(key)
 return None

